# train a Gaussian Naive Bayes classifier on the training set
from sklearn.naive_bayes import GaussianNB
# instantiate the model
gnb = GaussianNB()

# %% colab={"base_uri": "https://localhost:8080/"} id="1WYx_w_dAAsp" executionInfo={"status": "ok", "timestamp": 1725352356111, "user_tz": -180, "elapsed": 61940, "user": {"displayName": "Ahmed Yousry", "userId": "15736517196575255940"}} outputId="53721e14-a426-48cf-caac-5c743e71e383"
# Apply GaussianNB with grid search and print results with the best estimator

import numpy as np
from sklearn.model_selection import GridSearchCV

# defining parameter range
param_grid = {'var_smoothing': np.logspace(0,-9, num=100)}

grid = GridSearchCV(estimator=gnb,
                    param_grid=param_grid,
                    cv=5,
                    verbose=1,
                    scoring='accuracy')

# fitting the model for grid search
grid.fit(X_train, y_train)

# print best parameter after tuning
print(grid.best_params_)

# print how our model looks after hyper-parameter tuning
print(grid.best_estimator_)

best_nv=grid.best_estimator_

