# %% id="C1er_4Ig9np9" outputId="111f0619-0155-4a55-d107-c8c10c6dec0c" colab={"base_uri": "https://localhost:8080/"} executionInfo={"status": "ok", "timestamp": 1725352357595, "user_tz": -180, "elapsed": 684, "user": {"displayName": "Ahmed Yousry", "userId": "15736517196575255940"}}
