# %% [markdown] id="j4SUMGNw9np9"
# ### Classification accuracy

# %% id="tbfQHuyl9np9" executionInfo={"status": "ok", "timestamp": 1725352357595, "user_tz": -180, "elapsed": 36, "user": {"displayName": "Ahmed Yousry", "userId": "15736517196575255940"}}
TP = cm[0,0]
TN = cm[1,1]
FP = cm[0,1]
FN = cm[1,0]

# %% id="97SYBA9S9np9" outputId="8a3539af-ffc8-4f22-cb88-3a7463d96b57" colab={"base_uri": "https://localhost:8080/"} executionInfo={"status": "ok", "timestamp": 1725352357595, "user_tz": -180, "elapsed": 36, "user": {"displayName": "Ahmed Yousry", "userId": "15736517196575255940"}}
# print classification accuracy

classification_accuracy = (TP + TN) / float(TP + TN + FP + FN)

print('Classification accuracy : {0:0.4f}'.format(classification_accuracy))


